/* Game-local platform layout. Carriage and actor geometry stay source-owned. */
.pf-courtesy .app,.pf-courtesy .app.is-intro,.pf-courtesy .app.is-result,.pf-courtesy .app:not(.is-intro):not(.is-result){width:100%;max-width:min(980px,max(460px,calc((100dvh - 265px)*2.65 + 48px)));min-height:100dvh;height:auto;display:flex;flex-direction:column;justify-content:center;padding:16px 20px;gap:14px}
.pf-courtesy .pf-header{margin:0;grid-template-columns:auto minmax(0,1fr) auto}
.pf-courtesy .pf-header h1{transform:none;text-shadow:none}
.pf-courtesy .pf-header .header-actions{grid-column:2;grid-row:2;justify-self:end;height:44px}
.pf-courtesy .app .header-actions .hud{display:flex}
.pf-courtesy .app.is-intro .header-actions,.pf-courtesy .app.is-result .header-actions{visibility:hidden}
.pf-courtesy .app .round-layout{display:block;width:100%;flex:none;min-height:0}
.pf-courtesy .app .game-wrap{width:100%;height:auto;max-height:none;min-height:0;padding-top:0;align-self:auto}
.pf-courtesy .app #game{width:100%;height:auto;aspect-ratio:var(--carriage-ratio);max-height:none}
.pf-courtesy .controls{width:100%;padding-top:0}
.pf-courtesy #intro,.pf-courtesy #pause-overlay{display:none!important}
.pf-courtesy #result{padding:22px;display:block;text-align:left}
.pf-courtesy #result .result-card{width:100%;max-width:none}
.pf-courtesy #result .rank{font-size:62px;flex-shrink:0}
.pf-courtesy #result .result-heading{align-items:center}
.pf-courtesy #result .start{width:100%;min-height:48px;margin:16px 0;font-size:20px}
.pf-courtesy #result-photo{display:block;width:100%;height:auto;margin-top:16px;border-radius:12px}
.pf-courtesy #share-preview{width:100%;height:auto;user-select:auto;-webkit-touch-callout:default}
.pf-courtesy #share-text{user-select:text;-webkit-user-select:text;touch-action:pan-y}
.pf-courtesy .platform-ranking-note,.pf-courtesy .share-note{font-size:14px!important;color:#526c5b;line-height:1.5}
.pf-courtesy .pf-entry .help-body{overflow:visible;padding:0;scrollbar-gutter:auto}
.pf-courtesy .pf-entry :is(button,input),.pf-courtesy #result button{touch-action:manipulation}
@media(max-width:650px){
 .pf-courtesy .app,.pf-courtesy .app.is-intro,.pf-courtesy .app.is-result,.pf-courtesy .app:not(.is-intro):not(.is-result){max-width:100%;padding:12px;gap:12px;justify-content:flex-start}
 .pf-courtesy .pf-header{grid-template-columns:minmax(0,1fr) auto;gap:4px 6px}
 .pf-courtesy .pf-header>.pf-studio-heading{grid-column:1/-1;grid-row:2;padding-right:64px}
 .pf-courtesy .pf-header nav{grid-column:2;grid-row:1;display:flex;width:auto;gap:4px}
 .pf-courtesy .pf-header nav button{width:auto;min-width:44px;padding:0 7px}
 .pf-courtesy .pf-header .header-actions{grid-column:2;grid-row:2}
 .pf-courtesy .pf-header h1{font-size:20px;padding:0}
 .pf-courtesy .pf-header .pf-studio-live{font-size:9px}
 .pf-courtesy .action{min-height:72px}.pf-courtesy .action b{font-size:19px}
 .pf-courtesy .status-row p{font-size:16px}
}
@media(min-width:651px){.pf-courtesy .pf-header{grid-template-columns:auto minmax(0,1fr) auto auto}.pf-courtesy .pf-header nav{grid-column:4;grid-row:1}.pf-courtesy .pf-header .header-actions{grid-column:3;grid-row:1}}
@media(max-height:480px){.pf-courtesy .app{justify-content:flex-start}.pf-courtesy .pf-result-dialog{max-height:calc(100dvh - 24px)}}

import {createEntryShell} from '../shared/entry-shell.mjs';
import {syncPauseButton,createResultDialog} from '../shared/game-ui.mjs';
import {audioPreferences} from '../shared/audio-preferences.mjs';
import {recordPlayStart} from '../shared/play-counts.mjs';
import {copyResultFrame,createCourtesySharing} from './share.mjs';
const $=id=>document.getElementById(id),active=s=>['play','seating','depart'].includes(s.phase);
export function courtesyAudio(audio,music,prefs=audioPreferences()){
 const listeners=new Set();let last='';
 const note=audio.note.bind(audio),noise=audio.noise.bind(audio),startBuffer=music.startBuffer.bind(music);
 audio.note=(frequency,duration=.1,offset=0,type='triangle',volume=.045,end)=>note(frequency,duration,offset,type,volume*prefs.get().effectsVolume/.7,end);
 audio.noise=(duration=.16,volume=.07)=>noise(duration,volume*prefs.get().effectsVolume/.7);
 const volume=()=>{const v=prefs.get().musicVolume*.48;music.media.volume=v;if(music.gain)music.gain.gain.value=v;};
 music.startBuffer=(...args)=>{startBuffer(...args);volume();};
 function apply(){const p=prefs.get();audio.enabled=p.effectsEnabled;music.setEnabled(p.musicEnabled);volume();emit();}
 const getState=()=>{const p=prefs.get();return{...p,musicPlaying:!music.audio.paused,musicStatus:music.blocked?'error':music.loading?'loading':music.buffer?'ready':'locked',effectsStatus:audio.context?.state==='running'?'ready':'locked',suspended:music.pausedByGame,message:'聲音暫時無法播放，點擊音樂按鈕可重試。'};};
 function emit(){const next=JSON.stringify(getState());if(next!==last){last=next;for(const fn of listeners)fn();}}
 prefs.subscribe(apply);apply();
 return{getState,subscribe(fn){listeners.add(fn);return()=>listeners.delete(fn);},sync:emit,unlock(){audio.unlock();return music.play();},setMusicEnabled:musicEnabled=>prefs.set({musicEnabled}),setEffectsEnabled:effectsEnabled=>prefs.set({effectsEnabled}),setMusicVolume:musicVolume=>prefs.set({musicVolume}),setEffectsVolume:effectsVolume=>prefs.set({effectsVolume})};
}
export function installCourtesyPlatform(scene,audio,music){
 const sharing=createCourtesySharing(document),result=createResultDialog($('result'),{focusTarget:()=>$('result-title'),returnFocus:()=>$('toolbar-restart')});
 const advanced=$('instructions').querySelector('.help-body');advanced.removeAttribute('tabindex');
 const entry=createEntryShell({document,title:'客氣大賽',goal:'你先坐！不，你先坐！發車前坐穩才算贏。',operations:['←／你請坐：互讓完成才計次。','→／謝謝：立刻開始坐下，坐穩需 0.3 秒。','點搶座乘客／空白鍵趕人；倒數 30→20 後隱藏。'],advanced,canStart:()=>scene.ready,onStart:()=>scene.start(),onHelpEnter:()=>{if(active(scene)&&!scene.tabPaused)scene.pauseRound();}});
 const originalStart=scene.start.bind(scene),originalPause=scene.pauseRound.bind(scene),originalResume=scene.resumeRound.bind(scene);
 let captureSerial=0;
 scene.start=()=>{if(document.hidden||scene.starting)return;captureSerial++;sharing.reset();result.close();entry.close({restoreView:false});if(scene.tabPaused){scene.tabPaused=false;scene.scene.resume();$('pause-overlay').classList.add('hidden');}originalStart();sync();};
 scene.pauseRound=()=>{originalPause();if(scene.tabPaused){$('pause-overlay').classList.add('hidden');entry.openPause();entry.dialog.querySelector('[data-pf-pause]')?.append(help);}sync();};
 scene.resumeRound=()=>{if(document.hidden)return;entry.close({restoreView:false});originalResume();sync();};
 entry.configurePause({canContinue:()=>!document.hidden,onContinue:()=>scene.resumeRound(),onRestart:()=>scene.start()});
 const audioAdapter=courtesyAudio(audio,music);entry.setAudio(audioAdapter);
 document.querySelector('[data-pf-music-toggle]')?.setAttribute('data-game-action','music');$('sound').removeAttribute('data-game-action');
 const note=document.createElement('p');note.className='platform-ranking-note';note.textContent='平台排行榜尚未開放；目前只記錄遊玩次數。';entry.dialog.querySelector('details').prepend(note);
 const ranking=()=>{const text=document.createElement('section');text.innerHTML='<h2>平台排行榜尚未開放</h2><p>目前只記錄遊玩次數；成績不會上傳排名。</p>';entry.openView(text,{label:'客氣大賽平台排行榜'});};entry.setRankingAction(ranking);
 const help=document.createElement('button');help.className='pf-menu-row';help.textContent='操作說明與素材授權';help.onclick=()=>entry.open({help:true});entry.dialog.addEventListener('click',()=>{const root=entry.dialog.querySelector('[data-pf-pause]');if(root&&!root.contains(help))root.append(help);});
 $('toolbar-restart').onclick=()=>scene.start();$('toolbar-pause').onclick=()=>scene.tabPaused?scene.resumeRound():scene.pauseRound();$('restart').onclick=()=>scene.start();$('resume').onclick=()=>scene.resumeRound();
 window.addEventListener('blur',()=>scene.pauseRound());
 document.addEventListener('visibilitychange',()=>{if(!document.hidden&&scene.tabPaused){const resume=entry.dialog.querySelector('[data-pf-continue]');if(resume)resume.disabled=false;}});
 window.addEventListener('keydown',e=>{if(e.target?.closest?.('input,textarea,select,[contenteditable],dialog'))return;if(['p','P','Escape'].includes(e.key)&&active(scene)){e.preventDefault();scene.tabPaused?scene.resumeRound():scene.pauseRound();}});
 $('intro').hidden=true;$('intro').classList.add('hidden');document.querySelector('[data-pf-entry-loading]')?.remove();entry.open();sync();
 function sync(){syncPauseButton($('toolbar-pause'),{paused:scene.tabPaused,available:active(scene)});$('toolbar-restart').disabled=!scene.ready||scene.starting;audioAdapter.sync();}
 return{sync,started(){captureSerial++;sharing.reset();result.close();recordPlayStart(window,'courtesy-contest');sync();},finished(){
  sync();const token=++captureSerial,data={grade:$('rank').textContent,title:$('result-title').textContent,count:scene.count,bonus:scene.chainBonus,status:$('result-status-text').textContent,remaining:$('result-remaining').textContent};
  // Keep the stage geometry unchanged. Snapshot its actual final rendered pose.
  const capture=()=>{if(token!==captureSerial||scene.phase!=='result')return;try{sharing.prepare(copyResultFrame(document,scene.game.canvas),data);}catch{$('share-status').textContent='成績圖片暫時無法產生。';}result.open();};
  scene.game.events.once('postrender',capture);
 }};
}
let controller;
window.courtesyPlatform={ready(scene,audio,music){controller=installCourtesyPlatform(scene,audio,music);},started(){controller?.started();},finished(){controller?.finished();},sync(){controller?.sync();}};

import {buildThreadsIntent,copyResultText,saveResultImage} from '../long-jump/share.mjs';
// Copy inside Phaser's postrender task, before resize can clear its drawing buffer.
export function copyResultFrame(document,source){
 const frozen=document.createElement('canvas');frozen.width=source.width;frozen.height=source.height;
 frozen.getContext('2d').drawImage(source,0,0);return frozen;
}
export function createCourtesySharing(document){
 const win=document.defaultView,$=id=>document.getElementById(id),image=$('share-image'),threads=$('share-threads'),copy=$('share-copy'),status=$('share-status'),dialog=$('share-fallback');
 const route=win.location.origin+'/games/courtesy-contest/';
 let generation=0,file=null,frozen=null,result=null,value='',pending=false,copyPending=false,url=null,returnFocus=null;
 const mobile=()=>Boolean(win.matchMedia?.('(pointer:coarse)').matches);
 const release=()=>{if(url){win.URL.revokeObjectURL(url);url=null;}};
 function close(){if(dialog.open)dialog.close();returnFocus?.focus({preventScroll:true});release();$('share-preview').removeAttribute('src');}
 $('close-share').onclick=close;dialog.addEventListener('cancel',event=>{event.preventDefault();close();});
 function fallback(kind){release();returnFocus=document.activeElement;$('share-preview').hidden=kind!=='image';$('share-text').hidden=kind!=='text';$('fallback-note').textContent=kind==='image'?'長按圖片儲存或分享。':'請選取文字，長按或按 Ctrl/Cmd+C 複製。';if(kind==='image'){$('share-preview').src=url=win.URL.createObjectURL(file);}else{$('share-text').value=value;}if(!dialog.open)dialog.showModal();(kind==='text'?$('share-text'):$('close-share')).focus();if(kind==='text')$('share-text').select();return true;}
 function reset(){generation++;file=null;frozen=null;result=null;value='';pending=copyPending=false;close();image.disabled=true;image.textContent='製作成績圖…';copy.disabled=true;threads.removeAttribute('href');status.textContent='';$('result-photo').hidden=true;}
 function encode(){
  if(!frozen||!result)return;const token=generation;image.disabled=true;image.textContent='製作成績圖…';status.textContent='';
  const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=800;const c=canvas.getContext('2d');
  try{
   c.fillStyle='#fff8e8';c.fillRect(0,0,1080,800);c.fillStyle='#274b3c';c.font='700 25px Arial';c.fillText('PLAYFORMOSA STUDIO · 客氣大賽',48,56);
   c.font='800 52px Arial';c.fillText(result.grade+' · '+result.title,48,132,984);c.font='700 38px Arial';c.fillText(result.count+' 次互讓'+(result.bonus?' · 連鎖 +'+result.bonus:''),48,195,984);
   c.font='30px Arial';c.fillText(result.status+'　'+result.remaining,48,250,984);
   const h=Math.min(410,984*frozen.height/frozen.width),w=h*frozen.width/frozen.height;c.drawImage(frozen,(1080-w)/2,290,w,h);
   c.fillStyle='#476555';c.font='24px Arial';c.fillText(route,48,754,984);
   canvas.toBlob(blob=>{if(token!==generation)return;try{if(!blob?.size||blob.type!=='image/png')throw Error();file=new win.File([blob],'playformosa-courtesy-contest.png',{type:'image/png'});image.disabled=false;image.textContent=mobile()?'分享成績圖片':'下載成績圖片';}catch{failed();}},'image/png');
  }catch{failed();}
  function failed(){if(token!==generation)return;file=null;image.disabled=false;image.textContent='重試製作成績圖';status.textContent='圖片未能完成，可重試；成績文字仍可複製。';}
 }
 image.onclick=()=>{
  if(pending)return;if(!file){encode();return;}const token=generation;pending=true;image.disabled=true;
  // The helper invokes native share synchronously in this activation handler.
  const task=saveResultImage(file,{mobile:mobile(),navigator:{canShare:payload=>win.navigator.canShare?.(payload)??false,share:payload=>win.navigator.share({...payload,title:'客氣大賽'})},download:current=>{release();url=win.URL.createObjectURL(current);const a=document.createElement('a');a.href=url;a.download=current.name;a.click();},openImage:()=>fallback('image')});
  task.then(out=>{if(token!==generation)return;if(out.status==='error'||out.status==='unsupported'){fallback('image');status.textContent='未能直接分享，請長按圖片儲存。';}else status.textContent=out.status==='cancelled'?'已取消分享。':out.status==='handed-off'?'已開啟系統分享。':out.status==='downloaded'?'已送出圖片下載。':'請長按圖片儲存或分享。';}).finally(()=>{if(token===generation){pending=false;image.disabled=false;}});
 };
 copy.onclick=()=>{if(copyPending||!value)return;const token=generation;copyPending=true;copy.disabled=true;copyResultText({text:value},{clipboard:win.navigator.clipboard}).then(out=>{if(token!==generation)return;if(out.status==='copied')status.textContent='已複製成績與網址。';else fallback('text');}).finally(()=>{if(token===generation){copyPending=false;copy.disabled=false;}});};
 return{reset,prepare(frame,data){reset();frozen=frame;result={...data};value=`客氣大賽｜${data.title}\n${data.count} 次互讓${data.bonus?'，連鎖 +'+data.bonus:''}｜${data.status}\n${data.remaining}\n${route}`;threads.href=buildThreadsIntent({text:value});copy.disabled=false;const photo=$('result-photo');photo.width=frame.width;photo.height=frame.height;photo.getContext('2d').drawImage(frame,0,0);photo.hidden=false;encode();}};
}

// Final-round snapshots only. These adapters never read historical local bests.
export const BOARD_METRICS=Object.freeze({
 'long-jump':{rules:'journey-km-v1',unit:'km',status:'valid',direction:'desc'},
 hurdles:{rules:'110m-8h-v1',unit:'s',status:'done',direction:'asc'},
 'high-jump':{rules:'cleared-height-v1',unit:'m',status:'cleared',direction:'desc'},
 'pole-vault':{rules:'real-altitude-v3',unit:'m',status:'done',direction:'desc'},
 'shot-put':{rules:'relay-distance-v1',unit:'m',status:'valid',direction:'desc'},
 discus:{rules:'wind-ufo-distance-v1',unit:'m',status:'valid',direction:'desc'},
 'reaction-rod':{rules:'catch-rating-v1',unit:'catches',status:'done',direction:'desc',secondary:true},
 'beer-slide':{rules:'accuracy-retention-v1',unit:'points',status:'valid',direction:'desc'},
 'run-400m':{rules:'400m-prototype-v3',unit:'s',status:'done',direction:'asc'},
 'run-1500m':{rules:'1500m-ccw-tactics-v3',unit:'s',status:'done',direction:'asc'},
 'tower-climb':{rules:'indoor-10floors-v1',unit:'s',status:'summit',direction:'asc'}
});
export function resultToSubmission(game,r){
 const b=Object.hasOwn(BOARD_METRICS,game)?BOARD_METRICS[game]:null;
 if(!b||!r||r.phase!=='done')return null;
 let score;
 switch(game){
 case 'long-jump':if(r.valid!==true)return null;score=r.legalAdventureKm;break;
 case 'hurdles':score=r.t;if(score>180)return null;break;
 case 'high-jump':if(r.success!==true)return null;score=r.height;break;
 case 'pole-vault':if(r.ruleset!==b.rules||r.scoreSnapshot?.ruleset!==b.rules)return null;score=r.scoreSnapshot.height;break;
 case 'shot-put':if(r.valid!==true)return null;score=r.distance;break;
 case 'discus':if(r.foul!==false)return null;score=r.score;break;
 case 'reaction-rod':score=r.caught;if(!Number.isInteger(score)||score>10||!Number.isFinite(r.rating)||r.rating<0||r.rating>10)return null;break;
 case 'beer-slide':if(r.fallen||r.invalid||r.invalidReason||r.cancelled)return null;score=r.raw;if(score>10)return null;break;
 case 'run-400m':case 'run-1500m':if(r.finished!==true||r.ruleset!==b.rules||r.scoreSnapshot?.ruleset!==b.rules)return null;score=r.scoreSnapshot.seconds;break;
 case 'tower-climb':if(r.finished!==true||r.floor!==10)return null;score=r.time;if(score>60)return null;break;
 }
 if(game==='run-400m'&&(score<30||score>=3600))return null;
 if(typeof score!=='number'||!Number.isFinite(score)||score<=0)return null;
 return {score,status:b.status,...(b.secondary?{secondaryScore:r.rating}:{})};
}

import {createUploadCooldown} from './upload-cooldown.mjs';
import {LEADERBOARD_ENABLED} from './leaderboard-config.mjs';
import {bindManualUploadScroll} from './leaderboard-scroll.mjs';
export const formatLeaderboardScore=n=>n>0&&n<.001?'<0.001':n.toLocaleString(undefined,{maximumFractionDigits:3});
import {BOARD_METRICS as boards,resultToSubmission} from './leaderboard-metrics.mjs';
export const eligibleResult=resultToSubmission;
const displayUnits={km:'公里',s:'秒',m:'公尺',catches:'根',points:'分'};
const boardLabels={
 'long-jump':['跳遠','合法落地，越遠越好。'],hurdles:['110公尺跨欄','越快越好，欄杆不是扶手。'],
 'high-jump':['跳高','成功過桿高度，越高越好。'],'pole-vault':['撐竿跳','最高高度，四肢向天空報到。'],
 'shot-put':['鉛球','有效距離，重物也想去旅行。'],discus:['鐵餅','有效距離，跟著風去兜一圈。'],
 'reaction-rod':['接棒啦！','先比接住根數，再比評分。'],'beer-slide':['別灑啊！','準度與留酒率，一杯決勝負。'],
 'run-400m':['400公尺','固定跑道一圈，秒數越短越前面。'],
 'run-1500m':['1500公尺戰術賽','街機實際遊戲用時，非真實田徑紀錄。'],
 'tower-climb':['上樓不容易','十層完成時間，越短越前面。']
};
export function mountLeaderboard({document,game,entry,result,resultActionContainer=result,resultUploadContainer=result,resultActionLabel='查看榮譽榜',shell=null,enabled=LEADERBOARD_ENABLED,fetcher=(...args)=>document.defaultView.fetch(...args)}){
 if(!enabled||!Object.hasOwn(boards,game))return null;
 const win=document.defaultView,b=boards[game],make=(tag,text)=>{const n=document.createElement(tag);if(text)n.textContent=text;return n;};
 if(!document.querySelector('link[data-leaderboard-style]')){const l=make('link');l.rel='stylesheet';l.href='/games/shared/leaderboard.css';l.dataset.leaderboardStyle='';document.head.append(l);}
 const read=k=>{try{return win.localStorage.getItem(k);}catch{return null;}},write=(k,v)=>{try{win.localStorage.setItem(k,v);}catch{}};
 let device=read('pf-leaderboard-device-v1');if(!/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(device||'')){try{device=win.crypto.randomUUID();write('pf-leaderboard-device-v1',device);}catch{device=null;}}
 const note='提交後，暱稱與成績會公開在這個線上榜。紀錄認這個瀏覽器，不認同名；換裝置或清除資料不會自動連回。';
 const format=formatLeaderboardScore,gapText=n=>n>0&&n<.001?'<0.001':format(n),unitLabel=displayUnits[b.unit]||b.unit;
 const scoreLabel=row=>format(row.score)+' '+unitLabel+(b.secondary&&Number.isFinite(row.secondaryScore)?' · '+format(row.secondaryScore)+' 分':'');
 const gapLabel=row=>gapText(row.gap)+' '+(row.gapMetric==='rating'?'分':unitLabel);
 const ranking=make('details');ranking.className='pf-leaderboard';const rankingSummary=make('summary','榮譽榜');rankingSummary.className='pf-menu-row';ranking.append(rankingSummary);entry?.append(ranking);
 const content=make('section');content.className='pf-honor-board';const heading=make('header'),icon=make('img');icon.src='/assets/app-icons/'+game+'/apple-touch-icon.png';icon.alt='';icon.width=64;icon.height=64;const titles=make('div');titles.append(make('p','PLAYFORMOSA · 榮譽榜'),make('h2',boardLabels[game][0]));heading.append(icon,titles);
 const rule=make('p',boardLabels[game][1]+'休閒比一比，成績由玩家回報。');rule.className='pf-rank-rule';const own=make('section');own.dataset.ownBest='';own.className='pf-rank-own';const list=make('ol'),rankStatus=make('p');rankStatus.setAttribute('role','status');list.className='pf-rank-list';
 const foot=make('p','同分並肩站。');foot.className='pf-rank-foot';content.append(heading,rule,own,rankStatus,list,foot);ranking.append(content);
 let rankingBusy=false,rankTime=0,rankToken=0,rankAbort=null,rankTimer=null,boardOpen=false;
 function stopRanking(){rankToken++;rankAbort?.abort();rankAbort=null;win.clearTimeout(rankTimer);rankingBusy=false;}
 function drawOwn(row){own.replaceChildren(make('h3','我的線上最佳'));if(!row){own.append(make('p','榜上還缺你。取得有效成績後，到結算畫面提交。'));return;}own.append(make('strong',scoreLabel(row)),make('p','第 '+row.rank+' 名 · '+row.nickname),make('p',row.gap===null?'目前領先，繼續挑戰自己。':'追上前方成績還差 '+gapLabel(row)));}
