test('foul/DNF/zero/unfinished never upload; no score cap guessed for high distances',()=>{for(const[g,r]of[['long-jump',{valid:false,legalAdventureKm:10}],['high-jump',{success:false,height:9}],['shot-put',{valid:false,distance:9}],['discus',{foul:true,score:9}],['beer-slide',{raw:9,invalid:true}],['beer-slide',{raw:9,fallen:true}],['beer-slide',{raw:9,cancelled:true}],['tower-climb',{finished:false,floor:9,time:60}],['tower-climb',{finished:true,floor:10,time:60.1}],['reaction-rod',{caught:0,rating:0}]])assert.equal(resultToSubmission(g,{phase:'done',...r}),null);assert.equal(resultToSubmission('hurdles',{phase:'dnf',t:180}),null);assert.equal(resultToSubmission('high-jump',{phase:'done',success:true,height:1e100}).score,1e100);});

import test from 'node:test';
